test('lineVAT: VAT is calculated on amount after discount', () => {
  // 5 x 9500 = 47500, 10% discount = 4750
  // After discount: 42750, 21% VAT = 8977.5 -> 8978
  const vat = lineVAT({ qty: 5, unitPrice: 9500, vatRate: 21, discountPercent: 10 });
  assert.equal(vat, 8978);
});

