});

test('invoiceTotals: returns integers', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 100 },
      { qty: 2, unitPrice: 200 },
    ],
  };

  const totals = invoiceTotals(invoice);
  assert(Number.isInteger(totals.subtotal));
  assert(Number.isInteger(totals.total));
});

test('invoiceTotals: with invoice from createInvoice', () => {
  const result = createInvoice({
    customerId: 'C-002', // standard tier, no discount
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 }, // 10 * 9500 = 95000
      { sku: 'DES-HOUR', qty: 5 }, // 5 * 8500 = 42500
    ],
  });

  assert(result.ok);
  const totals = invoiceTotals(result.value);
  assert.equal(totals.subtotal, 137500);
  assert.equal(totals.total, 137500);
});

test('invoiceTotals: does not mutate invoice', () => {
  const invoice = {
    lines: [{ qty: 5, unitPrice: 9500 }],
  };
  const originalInvoice = JSON.parse(JSON.stringify(invoice));

  invoiceTotals(invoice);

  assert.deepEqual(invoice, originalInvoice);
});

test('addLine: adds a new line to invoice', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 5 }],
  });

  assert(result.ok);
  const addResult = addLine(result.value, { sku: 'DES-HOUR', qty: 3 });

