  assert.equal(addResult.value.lines[1].qty, 3);
  assert.equal(addResult.value.lines[1].name, 'Design work (hour)');
  assert.equal(addResult.value.lines[1].unitPrice, 8500);
});

test('addLine: increases qty if SKU already exists', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
