test('issueInvoice: different years get different numbering', () => {
  const invoice2025 = {
    customerId: 'C-001',
    issueDate: '2025-12-31',
    status: 'draft',
    lines: [{ sku: 'DEV-HOUR', qty: 5, name: 'Development (hour)', unitPrice: 9500, vatRate: 21 }],
  };

  const invoice2026 = {
    customerId: 'C-001',
    issueDate: '2026-01-01',
    status: 'draft',
    lines: [{ sku: 'DEV-HOUR', qty: 5, name: 'Development (hour)', unitPrice: 9500, vatRate: 21 }],
  };

  const existingNumbers = ['INV-2025-0005'];

  const issue2025 = issueInvoice(invoice2025, existingNumbers);
  assert(issue2025.ok);
  assert.equal(issue2025.value.number, 'INV-2025-0006');

  const issue2026 = issueInvoice(invoice2026, existingNumbers);
  assert(issue2026.ok);
  assert.equal(issue2026.value.number, 'INV-2026-0001');
});

