  const invoice = {
    lines: [{ qty: 5, unitPrice: 9500, vatRate: 21, discountPercent: 10 }],
  };

  const totals = invoiceTotals(invoice);
  // Subtotal: 47500
  // Discount: 4750
  // VAT on (47500 - 4750) = 21% of 42750 = 8977.5 -> 8978
  // Total: 47500 - 4750 + 8978 = 51728
  assert.equal(totals.subtotal, 47500);
  assert.equal(totals.discount, 4750);
  assert.equal(totals.vat, 8978);
  assert.equal(totals.total, 51728);
});

